import sys; sys.path.insert(0, "tools")
from gen_lib import maker
S, M, save = maker("bc06", 606)
# ---------- QCS (60) ----------
S("definition","mitose : 1 cellule mère → 2 cellules filles identiques","La mitose est :","un mécanisme de division qui donne, à partir d’une cellule mère, deux cellules filles identiques entre elles",["un mécanisme qui donne quatre cellules haploïdes","un mécanisme qui produit deux cellules différentes","un mécanisme de fusion de deux cellules"],"La mitose est la multiplication d’une cellule préexistante, appelée cellule mère.",3)
S("definition","cellules filles : mêmes informations génétiques","Quelle est la particularité génétique des deux cellules filles issues d’une mitose ?","Elles possèdent les mêmes informations génétiques que la cellule mère",["Elles possèdent la moitié des informations génétiques","Elles possèdent des informations génétiques différentes l’une de l’autre","Elles n’ont pas d’information génétique"],"Les deux cellules filles sont identiques entre elles.",3)
S("definition","cellule mère","Comment appelle-t-on la cellule qui se divise lors d’une mitose ?","La cellule mère",["La cellule fille","La cellule germinale","La cellule haploïde"],"La mitose est la multiplication d’une cellule préexistante.",3)
S("definition","cycle cellulaire : G1, S, G2 et M","De quelles phases le cycle cellulaire est-il composé ?","G1, S et G2 (l’interphase) et la phase M (la mitose)",["G1 et M uniquement","S et M uniquement","G0, G1 et G2"],"G1, S et G2 constituent l’interphase.",3)
S("definition","phase M = mitose proprement dite","Quelle phase du cycle cellulaire correspond à la mitose proprement dite ?","La phase M",["La phase G1","La phase S","La phase G2"],"Les phases G1, S et G2 constituent l’interphase.",3)
S("ordre","ordre des phases de la mitose","Quel est l’ordre des phases de la mitose ?","Prophase, métaphase, anaphase, télophase",["Métaphase, prophase, anaphase, télophase","Prophase, anaphase, métaphase, télophase","Télophase, prophase, métaphase, anaphase"],"La mitose compte quatre phases successives.",5)
S("definition","interphase : période entre deux divisions","Qu’est-ce que l’interphase ?","La période entre deux divisions cellulaires",["La phase de la division du noyau","La phase de séparation des chromatides","La dernière phase de la mitose"],"Elle comprend les phases G1, S et G2.",7)
S("definition","interphase : volume, gènes, ADN","Quelles sont les caractéristiques de l’interphase ?","Un accroissement du volume cellulaire, l’expression des gènes et la duplication de l’ADN (acide désoxyribonucléique)",["La condensation de la chromatine en chromosomes","La séparation des chromatides sœurs","La reformation de l’enveloppe nucléaire"],"Ces trois événements ont lieu entre deux divisions.",7)
S("definition","G1 : Growth 1","Que signifie G1 ?","Growth 1 : la cellule croît et vit normalement",["Une phase de synthèse d’ADN (acide désoxyribonucléique)","Une phase de séparation des pôles","Une phase de division du cytoplasme"],"G vient de l’anglais Growth.",7)
S("definition","G1 : cellules filles prennent leur taille finale","Que font les cellules filles issues de la mitose précédente pendant la phase G1 ?","Elles prennent leur taille finale",["Elles répliquent leur ADN (acide désoxyribonucléique)","Elles condensent leurs chromosomes","Elles se divisent à nouveau"],"Les cellules filles issues de la mitose précédente sont plus petites.",7)
S("definition","phase S : synthèse d’ADN","Que signifie la lettre S de la phase S ?","Synthèse de nouvelles molécules d’ADN (acide désoxyribonucléique)",["Séparation des chromatides","Séparation des pôles","Synthèse d’organites"],"C’est pendant cette phase que l’ADN est dupliqué.",7)
S("definition","G2 : croissance et organites","Que fait la cellule en phase G2 ?","Elle croît pour avoir suffisamment d’organites pour sa descendance",["Elle réplique son ADN (acide désoxyribonucléique)","Elle sépare ses chromatides","Elle forme le fuseau"],"G2 signifie Growth 2.",7)
S("definition","centrosome : deux centrioles et matériel péricentriolaire","De quoi le centrosome (MTOC) est-il composé ?","De deux centrioles perpendiculaires entourés de matériel péricentriolaire",["D’un nucléole et d’un ribosome","D’un seul centriole","De deux noyaux"],"MTOC : centre organisateur de microtubules.",8)
S("definition","signification de MTOC","Que signifie MTOC pour le centrosome ?","Centre organisateur des microtubules (Microtubule Organizing Center)",["Complexe de transport des organites cellulaires","Centre de multiplication des ovocytes","Chaîne de transfert d’oxygène cellulaire"],"Le centrosome est le centre organisateur des microtubules.",8)
S("definition","matrice centrosomale","Qu’est-ce que la matrice centrosomale ?","Le matériel amorphe formé du matériel péricentriolaire et d’une paire de centrioles",["Le noyau du centrosome","Un réseau de microfilaments d’actine","L’enveloppe du centrosome"],"Elle abrite la nucléation des microtubules.",9)
S("definition","anneau de gamma-tubuline : nucléation","Que contient le centrosome qui permet la nucléation des microtubules ?","Le complexe en anneau de γ-tubuline",["Des histones","Des lamines","Des ribosomes"],"La nucléation est le point de départ de la formation des microtubules.",9)
S("definition","réseau radiaire de microtubules","Quelle organisation de microtubules le centrosome possède-t-il ?","Un réseau radiaire de microtubules, avec des extrémités + et −",["Un réseau parallèle de microfilaments","Un réseau circulaire de lamines","Aucun réseau"],"Les microtubules sont nucléés à partir du centrosome.",9)
S("definition","trois fonctions du centrosome","Quelles sont les trois fonctions du centrosome en mitose ?","Former les deux pôles du fuseau, donner un centrosome à chaque cellule fille et déterminer le plan de division cytoplasmique",["Répliquer l’ADN (acide désoxyribonucléique), condenser la chromatine et fabriquer les nucléoles","Former l’enveloppe nucléaire, synthétiser les lipides et digérer les chromosomes","Dupliquer le noyau, fabriquer les ribosomes et exporter l’acide ribonucléique"],"Le centrosome aide à la formation des pôles du fuseau.",10)
S("definition","plan de division cytoplasmique","Que détermine le centrosome ?","Le plan de division cytoplasmique",["Le nombre de chromosomes","La forme du noyau","Le type cellulaire"],"Chaque cellule fille a son centrosome.",10)
S("definition","cycle du centrosome : duplication puis séparation","Comment le cours définit-il le cycle du centrosome ?","Une duplication suivie d’une séparation",["Une fusion suivie d’une disparition","Une disparition suivie d’une réplication","Une séparation suivie d’une fusion"],"Le centrosome se duplique en interphase.",11)
S("definition","interphase : centrosome dupliqué","Que se passe-t-il pour le centrosome pendant l’interphase ?","Il est dupliqué, mais les deux copies restent ensemble",["Il disparaît","Il se divise en quatre noyaux","Il se dissout"],"Il est dupliqué pendant la phase S.",11)
S("definition","début de phase M : le centrosome se scinde","Que se passe-t-il pour le centrosome au début de la phase M ?","Il se scinde en deux",["Il est dupliqué","Il disparaît","Il fusionne avec le noyau"],"Chaque paire de centrioles devient un centre organisateur des microtubules.",11)
S("definition","paire de centrioles → centre organisateur","Que devient chaque paire de centrioles au début de la mitose ?","Un centre organisateur des microtubules",["Un nucléole","Un kinétochore","Un chromosome"],"Les centrosomes s’éloignent ensuite l’un de l’autre.",11)
S("definition","asters","Comment appelle-t-on les faisceaux de microtubules irradiant en étoile autour de chaque centrosome ?","Les asters",["Les chromatides","Les kinétochores","Les nucléoles"],"Les asters forment les pôles du fuseau mitotique.",11)
S("definition","centrosome dupliqué en S : deux paires","Que contient le centrosome dupliqué en phase S ?","Deux paires de centrioles",["Un seul centriole","Un nucléole","Quatre noyaux"],"Les centrioles sont dupliqués en phase S.",12)
S("definition","prophase : chromatine → chromosome","Que devient le matériel génétique en prophase ?","Il passe de la forme chromatine à la forme chromosome",["Il passe de la forme chromosome à la forme chromatine","Il est dégradé","Il est exporté hors du noyau"],"C’est la condensation de l’ADN (acide désoxyribonucléique).",15)
S("definition","prophase : nucléoles disparaissent","Que deviennent les nucléoles en prophase ?","Ils disparaissent",["Ils apparaissent","Ils se dupliquent","Ils fusionnent avec le centrosome"],"Ils se reforment en télophase.",15)
S("definition","cohésine entre chromatides sœurs","Quelle protéine relie les deux chromatides sœurs d’un chromosome au niveau du centromère ?","La cohésine",["La kinésine","La dynéine","La lamine"],"Les chromatides sœurs sont reliées par leur centromère.",15)
S("chiffre","centrosome de prophase : 4 centrioles","Combien de centrioles le centrosome contient-il en prophase, avant de se diviser en deux ?","4",["2","1","8"],"Il se divise ensuite en deux centrosomes.",15)
S("definition","centrosomes migrent vers les pôles","Que fait chacun des deux centrosomes en prophase ?","Il migre vers un pôle de la cellule",["Il reste près du noyau","Il entre dans le nucléole","Il fusionne avec l’autre centrosome"],"Les deux centrosomes forment les pôles.",15)
S("definition","fuseau mitotique : réorganisation du cytosquelette","D’où provient le fuseau mitotique ?","De la réorganisation du cytosquelette de microtubules",["Du Golgi","Du nucléole","De la paroi"],"Il se forme en prophase.",15)
S("definition","prométaphase : membrane nucléaire en vésicules","Que devient la membrane nucléaire en prométaphase ?","Elle se désagrège sous forme de vésicules",["Elle se renforce","Elle se duplique","Elle se reforme"],"Elle se reforme en fin de télophase.",17)
S("definition","kinétochores aux centromères","Où se forment les kinétochores ?","Au niveau des centromères",["Aux pôles","Sur le nucléole","Dans le cytosol"],"Ils se forment en prométaphase.",17)
S("definition","kinétochore : complexe protéique","Qu’est-ce qu’un kinétochore ?","Un complexe protéique spécialisé auquel s’accrochent certains microtubules",["Une protéine qui relie les chromatides","Un organite membranaire","Un type de microtubule astral"],"Chaque chromatide est ainsi reliée à un pôle.",17)
S("definition","mouvements agités en prométaphase","Pourquoi les chromosomes ont-ils des mouvements agités en prométaphase ?","Les microtubules exercent des tensions sur eux",["Ils sont répliqués","Ils sont dégradés","La membrane nucléaire se reforme"],"Les tensions viennent des microtubules reliés aux pôles.",17)
S("definition","chaque chromatide reliée à un pôle","À quoi chaque chromatide est-elle reliée à la fin de la prométaphase ?","À un pôle, par l’intermédiaire des microtubules",["À un nucléole","À la membrane plasmique","À l’autre chromatide sœur seulement"],"Cela entraîne des mouvements agités.",17)
S("chiffre","trois classes de microtubules","Combien de classes de microtubules le fuseau comprend-il ?","3",["2","4","1"],"Les microtubules astraux, du kinétochore et chevauchants.",18)
S("definition","microtubules astraux : pôles et orientation","Quel est le rôle des microtubules astraux ?","Séparer les pôles et orienter le fuseau dans la cellule",["Fixer les chromosomes au fuseau","Assurer la symétrie bipolaire","Dégrader les chromatides"],"Ils irradient dans toutes les directions.",18)
S("definition","microtubules kinétochoriens : fixent les chromosomes","Quel est le rôle des microtubules du kinétochore ?","Fixer les chromosomes au fuseau",["Séparer les pôles","Orienter le fuseau","Former les asters"],"Ils sont liés au kinétochore.",18)
S("definition","microtubules chevauchants : symétrie bipolaire","Quel est le rôle des microtubules chevauchants (polaires) ?","Assurer la symétrie bipolaire du fuseau",["Fixer les chromosomes","Irradier dans toutes les directions","Constituer le kinétochore"],"On les appelle aussi microtubules polaires.",18)
S("definition","extrémités − vers le centrosome","Vers quoi sont orientées toutes les extrémités − des microtubules du fuseau ?","Vers le centrosome",["Vers l’équateur","Vers le noyau","Vers la membrane"],"Les extrémités + sont dirigées vers les chromosomes.",19)
S("definition","plaque équatoriale","Comment appelle-t-on l’alignement des chromosomes à l’équateur de la cellule en métaphase ?","La plaque équatoriale",["Le fuseau","L’aster","La plaque nucléaire"],"Les chromosomes sont alignés selon leur centromère.",21)
S("definition","métaphase : alignement selon le centromère","Selon quelle partie du chromosome les chromosomes sont-ils alignés en métaphase ?","Leur centromère",["Leur nucléole","Leurs bras longs","Leurs télomères"],"Ils se déplacent vers l’équateur.",21)
S("definition","anaphase : phase très rapide","Comment est l’anaphase ?","Une phase très rapide",["La phase la plus longue","Une phase réversible","Une phase sans mouvement"],"Les chromatides se séparent et migrent vers les pôles.",22)
S("definition","anaphase : séparation des chromatides","Que se passe-t-il en anaphase ?","Les chromatides sœurs se séparent et migrent vers les pôles opposés",["Les chromosomes se condensent","L’enveloppe nucléaire se reforme","Le centrosome se duplique"],"C’est une phase très rapide.",22)
S("definition","chromatides tirées par les microtubules","Par quoi les chromatides sœurs sont-elles tirées en anaphase ?","Les microtubules, en direction du pôle auquel elles sont rattachées",["Les microfilaments d’actine","Les lamines","Les kératines"],"Elles sont tirées vers le pôle auquel elles sont rattachées.",22)
S("definition","télophase : microtubules disparaissent","Que deviennent les microtubules en télophase ?","Ils disparaissent",["Ils se forment","Ils se multiplient","Ils se fixent au noyau"],"Les chromatides commencent à se décondenser.",23)
S("definition","télophase : inverse de la prophase","Comment le cours caractérise-t-il la télophase par rapport à la prophase ?","C’est l’inverse de la prophase",["C’est la phase la plus rapide","C’est la même phase","C’est la phase de condensation"],"L’enveloppe nucléaire et les nucléoles se reforment.",23)
S("definition","télophase : décondensation","Que deviennent les chromatides sœurs en télophase ?","Elles commencent à se décondenser",["Elles se condensent","Elles se dupliquent","Elles sont dégradées"],"L’enveloppe nucléaire et les nucléoles commencent à se reformer.",23)
S("definition","enveloppe nucléaire : se reforme en fin de télophase","Quand l’enveloppe nucléaire se reforme-t-elle ?","En fin de télophase",["En prophase","En métaphase","En anaphase"],"Elle disparaît au cours de la prophase.",26)
S("definition","enveloppe nucléaire : disparaît en prophase","À quel moment l’enveloppe nucléaire disparaît-elle ?","Au cours de la prophase",["Au cours de la télophase","Au cours de l’anaphase","Au cours de l’interphase"],"Elle se reforme en fin de télophase.",26)
S("definition","absence d’enveloppe : séparation des chromosomes","Que permet l’absence d’enveloppe nucléaire pendant la mitose ?","Le déplacement et la séparation des chromosomes en deux lots répartis aux deux pôles",["La réplication de l’ADN (acide désoxyribonucléique)","La transcription des gènes","La traduction des protéines"],"Il n’y a pas de métabolisme de l’ADN pendant la mitose.",26)
S("definition","chromosome en début de mitose : 2 chromatides","Comment sont formés les chromosomes en début de mitose ?","De deux chromatides unies au niveau des centromères",["D’une seule chromatide","De quatre chromatides","D’un seul brin d’acide ribonucléique"],"Ils sont répliqués avant la mitose.",26)
S("chiffre","après l’anaphase : 1 chromatide","Combien de chromatides chaque chromosome a-t-il après l’anaphase ?","Une seule",["Deux","Quatre","Aucune"],"Les deux chromatides de chaque chromosome se séparent et forment deux lots de chromosomes.",26)
S("definition","squelette cytoplasmique en interphase","De quoi est formé le squelette cytoplasmique de la cellule en dehors de la mitose ?","Essentiellement de microtubules dispersés dans la cellule",["De microtubules organisés en fuseau","De filaments d’actine concentrés au centre","De lamines"],"Pendant la mitose, les microtubules s’organisent de manière particulière.",27)
S("definition","centrosomes : près du noyau puis opposés","Comment se disposent les deux centrosomes au début de la mitose ?","Près du noyau, puis l’un d’eux migre du côté opposé",["Aux deux pôles d’emblée","Dans le noyau","Contre la membrane plasmique"],"Chaque centrosome forme alors un réseau de microtubules.",27)
S("definition","microtubules du fuseau : déplacement orienté","Que permettent les microtubules du fuseau de division ?","Le déplacement orienté des chromosomes",["La synthèse des chromosomes","La dégradation de la chromatine","La reformation du nucléole"],"Le fuseau se dispose au niveau du noyau.",27)
S("definition","colchicine : fuseau et répartition anarchique","Quel effet la colchicine a-t-elle sur la mitose ?","Elle empêche la formation du fuseau et entraîne une répartition anarchique des chromosomes",["Elle bloque la réplication de l’ADN (acide désoxyribonucléique) en phase S","Elle empêche la disparition de l’enveloppe nucléaire","Elle détruit la cohésine"],"La colchicine est une drogue cellulaire.",27)
S("cas_pratique","colchicine : cas pratique","Une cellule traitée par la colchicine entre en mitose. Quelle observation est attendue ?","Les chromosomes sont répartis de façon anarchique entre les deux cellules filles",["Les chromosomes sont répartis de façon identique entre les deux cellules filles","Les chromosomes ne se condensent pas","Le centrosome ne se duplique pas"],"Sans fuseau, les chromosomes ne sont pas déplacés de façon orientée.",27)
S("identification","identification métaphase : plan équatorial","Une cellule observée au microscope présente ses chromosomes alignés sur un plan équatorial. De quelle phase s’agit-il ?","La métaphase",["La prophase","L’anaphase","La télophase"],"Les chromosomes forment la plaque équatoriale.",21)

